class Solution { public: vector<vector<string>> suggestedProducts(vector<string>& products,string searchWord){sort(products.begin(),products.end());vector<vector<string>> answer;string prefix;for(char ch:searchWord){prefix+=ch;auto start=lower_bound(products.begin(),products.end(),prefix);vector<string> suggestions;for(auto it=start;it!=products.end()&&suggestions.size()<3&&it->rfind(prefix,0)==0;++it)suggestions.push_back(*it);answer.push_back(suggestions);}return answer;} };
